    ('RK_ISMENG_2019H1_YY', 'RK_ISMENG_2019H1_YY_Q054', 'IT系统管理工作的H部门人员管理包括IT组织及职责设计、IT人员的教育与培训及第三方/外包的管理。其中IT组织设计原则涉及多方面内容，下面( )不属于这些组织设计原则应考虑的内容。', 54, '单选题', '[{"key":"A","text":"IT部门应该设立清晰的愿景和目标","scores":{"score":0}},{"key":"B","text":"根据IT部门的服务内容重新思考和划分部门职能","scores":{"score":0}},{"key":"C","text":"扩充IT系统支持人员","scores":{"score":1}},{"key":"D","text":"建立目标管理制度、项目管理制度","scores":{"score":0}}]', '{"questionType":"单选题","sourceQuestionNo":54,"imageHashValues":[],"correctOptionKey":"C"}')
