    ('RK_ISMENG_2019H1_YY', 'RK_ISMENG_2019H1_YY_Q069', '信息系统评价中，系统效益评价指的是对系统的经济效益和社会效益等做出评价，可以分为经济效益评价和社会效益评价。经济效益评价又称为直接效益评价。一个企业信息化的收益包括产值增加所获得的利润收益和产品生产成本降低所节约的开支。下列选项中，( )不在产品生产成本降低所节约的开支之列。', 69, '单选题', '[{"key":"A","text":"由于系统实施而导致的销售产值的增加","scores":{"score":1}},{"key":"B","text":"采购费用的降低","scores":{"score":0}},{"key":"C","text":"人工费及通信费的减少","scores":{"score":0}},{"key":"D","text":"库存资金的减少","scores":{"score":0}}]', '{"questionType":"单选题","sourceQuestionNo":69,"imageHashValues":[],"correctOptionKey":"A"}')
